{
  "ok": true,
  "tool": "list_operations",
  "operations": [
    {
      "op": "stretch",
      "category": "edit",
      "description": "AutoCAD STRETCH with a crossing window: entities entirely inside move; LINE end points, polyline vertices and dimension definition points inside the window move; circles/arcs/text/blocks move if their center/insert point is inside. Dimensions are re-measured.",
      "params": {
        "type": "object",
        "properties": {
          "window": {
            "type": "array",
            "items": {
              "type": "array"
            },
            "description": "Two opposite corners of the crossing window list of [x, y] (or [x, y, bulge]) (drawing units, or string with unit e.g. '8mm')"
          },
          "delta": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Displacement [dx, dy] [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "window",
          "delta"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "modify",
      "category": "edit",
      "description": "Set fields of ONE entity, e.g. {target, set: {radius: 5}} for a circle, {set: {start: [0,0], end: [10,0]}} for a line, {set: {points: [...], closed: true}} for a polyline, {set: {text: 'A'}} for text, {set: {text: '4X <>', text_height: 3.5, length_factor: 2}} for a dimension.",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "set": {
            "type": "object",
            "description": "Field -> new value"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target",
          "set"
        ],
        "additionalProperties": false
      }
    }
  ],
  "count": 2,
  "detail": true,
  "constraint_types": {
    "check": [
      "angle",
      "coincident",
      "concentric",
      "diameter",
      "distance",
      "equal",
      "fixed",
      "horizontal",
      "length",
      "parallel",
      "perpendicular",
      "radius",
      "symmetric",
      "tangent",
      "vertical"
    ],
    "enforce": [
      "coincident",
      "concentric",
      "diameter",
      "distance",
      "equal",
      "fixed",
      "horizontal",
      "length",
      "parallel",
      "perpendicular",
      "radius",
      "vertical"
    ]
  },
  "metrics": {
    "duration_ms": 0.1,
    "input_bytes": 42,
    "output_bytes": 2559
  }
}

